//! Role: 解析設定と、モジュール階層・参照・循環の解析結果を定義する。
use std::{collections::BTreeSet, path::PathBuf};

/// Default maximum number of Unicode scalar values in a Role description.
pub const DEFAULT_MAX_ROLE_CHARS: usize = 80;

#[derive(Debug, Clone)]
pub struct AnalysisOptions {
    /// Lines in rustc --print cfg form, e.g. unix or target_os="linux".
    pub cfg: BTreeSet<String>,
    pub features: BTreeSet<String>,
    /// Explicit assumptions: these macros preserve the source module hierarchy.
    /// References generated by their expansion are outside source-level analysis.
    pub trusted_attributes: BTreeSet<String>,
    pub trusted_derives: BTreeSet<String>,
    /// Positive maximum number of Unicode scalar values in a Role description.
    pub max_role_chars: usize,
}

impl Default for AnalysisOptions {
    fn default() -> Self {
        Self {
            cfg: BTreeSet::new(),
            features: BTreeSet::new(),
            trusted_attributes: BTreeSet::new(),
            trusted_derives: BTreeSet::new(),
            max_role_chars: DEFAULT_MAX_ROLE_CHARS,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Module {
    pub id: String,
    pub file: PathBuf,
    pub parent: Option<String>,
    /// Static inner doc Role description, without its Role: marker.
    pub role: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct Reference {
    pub from: String,
    pub to: String,
}

#[derive(Debug, Clone)]
pub struct ModuleGraph {
    pub modules: Vec<Module>,
    pub edges: Vec<Reference>,
    /// Strongly connected components with at least two modules.
    pub cycles: Vec<Vec<String>>,
    pub diagnostics: Vec<String>,
}
